with supplier_stats as (select supplier_id, max(price) - min(price) as price_range, max(stock_qty) as max_stock_qty from products where size(tags) > 2 group by supplier_id) select suppliers.id, suppliers.supplier_name, supplier_stats.price_range, supplier_stats.max_stock_qty from suppliers left join supplier_stats on suppliers.id = supplier_stats.supplier_id order by price_range desc
